import type { HistoryActivity, HistoryBlock, HistoryChapter, HistoryChoice, HistoryLesson, HistoryQuizQuestion, HistorySource, HistoryTerm } from "./kanab-quest-school-history-types";

const sid = (key: string) => "harvest-lesson-" + key;
const tid = (key: string) => "harvest-term-" + key;
const lid = (chapter: string, part: number) => "harvest-" + chapter + "-" + part;
function source(key: string, title: string, author: string, organization: string, published: string, url: string, passage: string, access: HistorySource["access"], limitation: string): HistorySource {
  return { id: sid(key), title, author, organization, published, url, passage, access, limitation, verifiedAt: "2026-11-12", documentKind: "Source méthodologique, scientifique ou de filière originale ; nature précisée dans le titre" };
}
export const HARVEST_LESSON_SOURCES: readonly HistorySource[] = [
  source("hemp", "Chanvre — Guide de culture 2026", "Louis-Marie Allard ; coordination I. Lartigot ; contributions InterChanvre et partenaires", "Terres Inovia", "Janvier 2026", "https://www.terresinovia.fr/sites/default/files/2026-01/guide_culture_chanvre_2026.pdf", "Pages imprimées 8 et 22–23 : contractualisation, débouchés graine/fibre, pertes et conservation ; intégrité, échauffement et oxydation des graines.", "excerpt", "Seuls les principes et critères de qualité sont retenus. Aucun réglage de machine, calendrier, objectif d’humidité, durée ou température de conduite n’est repris. Les chiffres pédagogiques A/B/C ne proviennent pas du guide."),
  source("moisture", "Adjusting Crop Yield to a Standard Moisture Content — SS-AGR-443", "Michael J. Mulvaney, Pratap Devkota et Hardeep Singh", "University of Florida, IFAS Extension", "Publication initiale mai 2020 ; révision avril 2025 ; DOI 10.32473/edis-ag442-2020", "https://ask.ifas.ufl.edu/publication/AG442/pdf", "Pages 1–2 : eau rapportée à la masse humide, matière sèche, erreur de calcul courante et normalisation des rendements.", "excerpt", "PDF original consulté ; la page HTML bouclait en redirection. Les exemples et humidités commerciales d’autres cultures ne sont pas transférés au chanvre. Les pourcentages A/B/C sont entièrement fictifs, pas des cibles de conservation."),
  source("trials", "How to do research on your farm", "Paulo Pagliari et Bruce Potter", "University of Minnesota Extension", "Révision 2022 ; consulté le 12 novembre 2026", "https://extension.umn.edu/courses-and-events/for-professionals/on-farm-research/how-to-do-research-on-your-farm", "Keep things consistent ; Compare things more than once ; Randomize ; Beware of replication that isn’t ; limites d’extrapolation.", "excerpt", "Principes de comparaison, pas recommandations agronomiques transférées au chanvre. Les nombres de répétitions proposés dans le guide ne sont pas présentés comme un seuil universel de validité ; sous-échantillons et unités indépendantes sont distingués."),
  source("question", "How to Conduct Research on Your Farm or Ranch — The Process", "David Chaney", "SARE Outreach", "2017", "https://www.sare.org/publications/how-to-conduct-research-on-your-farm-or-ranch/how-to-develop-an-on-farm-research-project/the-process/", "Étapes 1–3 et 7–10 : question, hypothèse, variables à mesurer, journal, analyse et conclusion ; encadré Drawing Conclusions.", "excerpt", "Démarche pédagogique originale ; les exemples de pratiques et résultats d’autres cultures ne sont pas des programmes à reproduire. Un indicateur utile doit répondre à la question posée, pas à toutes les questions possibles."),
  source("blocks", "NIST/SEMATECH e-Handbook — 5.3.3.2. Randomized block designs", "NIST et SEMATECH, équipe du manuel statistique", "National Institute of Standards and Technology", "Page du manuel consultée le 12 novembre 2026 ; date de révision non confirmée", "https://www.itl.nist.gov/div898/handbook/pri/section3/pri332.htm", "Définition des facteurs de nuisance, blocs et randomisation à l’intérieur des blocs.", "official-page", "Méthodologie générale ; les exemples industriels ne sont pas présentés comme essais de chanvre. Un bloc aide à prendre en compte une hétérogénéité identifiée, sans rendre tous les biais impossibles."),
  source("causal", "NIST/SEMATECH e-Handbook — 3.1.3.6. Experiments and Experimental Design", "NIST et SEMATECH, équipe du manuel statistique", "National Institute of Standards and Technology", "Page du manuel consultée le 12 novembre 2026 ; date de révision non confirmée", "https://www.itl.nist.gov/div898/handbook/ppc/section1/ppc136.htm", "Définitions de corrélation et causalité ; rôle possible d’un troisième facteur ; articulation observation et expérience.", "official-page", "Une association seule ne démontre pas une cause. Le cours ne prétend pas que seules les expériences permettent toute inférence causale ; il examine les limites des petites comparaisons proposées."),
  source("budget", "Partial Budgeting for Agricultural Businesses", "Penn State Extension, équipe de gestion des entreprises agricoles", "Pennsylvania State University", "Mise à jour du 13 janvier 2026", "https://extension.psu.edu/partial-budgeting-for-agricultural-businesses", "Passages originaux indexés : coûts et revenus qui changent, nombres incertains, scénarios et facteurs non économiques.", "excerpt", "Ouverture directe refusée ; texte original substantiel consulté dans l’index. Méthode de comparaison, pas prévision financière d’une exploitation. Le budget partiel ne représente pas automatiquement le coût complet ni l’évolution de la valeur de l’argent."),
  source("charter", "Charte d’engagement de la filière chanvre", "InterChanvre et organisations signataires", "InterChanvre", "2022", "https://interchanvre.org/documents/5.actu_presse/documents_de_reference/2022_Charte_engagement.pdf", "Pages imprimées 6–9 : identification de chaîne, enregistrement des pratiques, hygiène, séparation des matières et contrôle des lots.", "excerpt", "Engagement professionnel daté, pas preuve que chaque lot respecte ces engagements. Les anciens seuils juridiques, chiffres de performance, promesses nutritionnelles et slogans environnementaux du document ne sont pas repris."),
  source("methods", "Validating analytical methods in cannabis testing", "Santé Canada", "Gouvernement du Canada", "Page courante consultée le 12 novembre 2026", "https://www.canada.ca/en/health-canada/services/cannabis-regulations-licensed-producers/validating-analytical-methods-cannabis-testing.html", "Passages originaux sur matrice, validation, résultats, unités, limites et incertitude ; lecture ciblée et indexée.", "excerpt", "Principes analytiques, sans protocole ni transfert de seuil canadien en France. Une mesure de fleurs est ici un objet documentaire de qualité ; aucun objectif d’augmentation des cannabinoïdes ni usage humain n’en est déduit."),
  source("oil", "Monitoring the Shelf Life of Hemp Seed Oil Stored at Two Temperatures in Different Materials via Near-Infrared (NIR) Spectroscopy", "Francesca Bonazza, Lucia Monti, Milena Povolo, Andrea Gasparini, Valeria Pelizzola et Giovanni Cabassi", "Molecules 29(23):5577", "26 novembre 2024 ; DOI 10.3390/molecules29235577", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11643794/", "Résumé, introduction et conclusion : évolution de marqueurs d’oxydation selon conditions et conditionnement.", "excerpt", "Une huile de graines et des conditions expérimentales particulières. Pas de durée de conservation universelle ni de paramètres pratiques repris. Ces résultats sur huile ne quantifient pas directement les pertes des lots fictifs de graines."),
  source("context", "Soil microbiome indicators can predict crop growth response to large-scale inoculation with arbuscular mycorrhizal fungi", "Stefanie Lutz, Natacha Bodenhausen et collaborateurs", "Nature Microbiology 8:2277–2289", "29 novembre 2023 ; DOI 10.1038/s41564-023-01520-w", "https://pmc.ncbi.nlm.nih.gov/articles/PMC10730404/", "Résumé, résultats Maize growth responses vary strongly et figure 2 ; figure 3 et discussion : réponse contextuelle et colonisation distincte du bénéfice.", "excerpt", "Essais dans 54 champs de maïs suisses, pas de chanvre. Le critère de croissance/biomasse de l’étude n’est pas assimilé à un rendement en graines commercialisables. Les modalités agronomiques et pourcentages d’effet ne sont pas transférés."),
  source("buddy", "Fiches Buddies du Quartier — Carmagnola, HH2026-045", "Équipe éditoriale Kanab Quest", "Kanab Quest", "Fiche relue le 30 octobre 2026 ; consultée le 12 novembre 2026", "/arene/placard?view=shop&tab=collection&section=buddies&buddy=HH2026-045", "Entrée HH2026-045 de src/data/buddie-varieties/027-052.json : histoire piémontaise, semences, fibres et cordages.", "catalogue", "Attribution à la fiche réelle du jeu, accessible sans possession. Une histoire d’usages ne démontre ni rendement, ni résistance, ni conformité du lot actuel."),
];
const sourceMap = new Map(HARVEST_LESSON_SOURCES.map(s => [s.id, s]));
const refs = (keys: readonly string[]) => keys.map(key => { const s = sourceMap.get(sid(key)); if (!s) throw new Error("Unknown harvest source " + key); return s; });
const block = (text: string, keys: readonly string[], evidence: HistoryBlock["evidence"] = "interpretation"): HistoryBlock => ({ text, evidence, sourceIds: keys.map(sid) });
type Row = readonly [string, string, boolean, string];
const choices = (rows: readonly Row[]): readonly HistoryChoice[] => rows.map(([id, text, correct, feedback]) => ({ id, text, correct, feedback }));
function activity(ch: string, part: number | "checkpoint", kind: HistoryActivity["kind"], title: string, scenario: string, prompt: string, rows: readonly Row[], reasons: readonly Row[], takeaway: string, keys: readonly string[]): HistoryActivity {
  return { id: "harvest-" + ch + (part === "checkpoint" ? "-checkpoint" : "-activity-" + part), kind, title, scenario, fictional: true, evaluates: prompt, steps: [{ id: "decision", prompt, choices: choices(rows), reasonPrompt: "Quelle raison soutient votre conclusion ?", reasons: choices(reasons), sourceIds: keys.map(sid) }], takeaway };
}
type Draft = { title: string; question: string; objective: string; essential: readonly string[]; example: string; deeper: string; nodes: readonly (readonly [string, string])[]; activity: HistoryActivity; terms: readonly string[]; next: string; keys: readonly string[]; buddyCodes?: readonly string[] };
function lesson(ch: string, part: number, d: Draft): HistoryLesson {
  return { id: lid(ch, part), title: d.title, question: d.question, objective: d.objective, minutes: 4, essential: d.essential.map(t => block(t, d.keys)), example: block(d.example, d.keys, "fiction"), deeper: [block(d.deeper, d.keys)], visual: { kind: "comparison", title: d.question, nodes: d.nodes.map(([label, detail]) => ({ label, detail })), caption: "Raisonnement qualitatif ; tous les chiffres d’exercice sont fictifs, sans cible ni programme de conduite.", sourceIds: d.keys.map(sid) }, activity: d.activity, glossaryIds: d.terms.map(tid), relatedLessonIds: [lid(ch, part === 1 ? 2 : 1)], nextQuestion: d.next, ...(d.buddyCodes ? { buddyCodes: d.buddyCodes } : {}) };
}

const outcomesLessons = [
  lesson("outcomes", 1, { title: "Définir ce qui s’améliore", question: "Quel lot gagne lorsque l’indicateur change ?", objective: "Comparer trois lots sur une base explicitement choisie.",
    essential: ["Améliorer une récolte peut signifier obtenir plus de matière, davantage de produit commercialisable, une qualité plus régulière ou moins de pertes et de ressources engagées. Ces objectifs ne sont pas identiques. Le résultat doit nommer un produit, un périmètre, une période et un indicateur. Une masse brute plus élevée peut simplement provenir d’une plus grande surface ou de davantage d’eau.", "Les trois lots fictifs A, B et C proviennent de zones distinctes d’une même campagne, avec le même débouché graines. Leur rendement brut humide par hectare est identique. Leur matière sèche et leur fraction commercialisable diffèrent. Aucun classement unique ne remplace donc la question initiale, et ces observations seules n’expliquent pas les causes des écarts."],
    example: "Tout est fictif : A, B et C donnent chacun 1 500 kg bruts humides/ha ; leurs quantités commercialisables en matière sèche sont respectivement 1 020, 840 et 1 080 kg MS/ha.",
    deeper: "Le brut total vaut 1 200 kg pour A, 1 800 pour B et 1 500 pour C, mais les surfaces sont différentes. B domine donc en masse brute totale sans dominer par hectare ni sur le critère commercialisable sec. Les chiffres servent à lire des indicateurs, pas à annoncer des performances réalistes ou souhaitables. Les zones ne sont pas un essai avant/après : leurs différences peuvent avoir plusieurs origines. Il faut documenter ces origines avant d’attribuer un avantage à une pratique.", nodes: [["Question", "Quel produit et quel objectif ?"], ["Comparaison", "Même unité, base et périmètre"], ["Conclusion", "Classement limité au critère choisi"]],
    activity: activity("outcomes", 1, "dossier", "Analyser trois lots", "Données fictives : A/B/C = 1 500 kg bruts humides/ha chacun ; commercialisable sec = 1 020/840/1 080 kg MS/ha. Même campagne et cahier des charges, zones distinctes.", "Quelle conclusion est exacte ?", [["a", "C a le plus de matière sèche commercialisable par hectare dans ce dossier.", true, "1 080 dépasse 1 020 et 840 pour ce critère précis."], ["b", "Les trois lots sont équivalents sur tous les critères puisque leur brut/ha est égal.", false, "Le critère commercialisable sec montre une différence."], ["c", "Les chiffres prouvent quelle pratique a causé les écarts.", false, "Aucune comparaison contrôlée de pratiques n’est fournie."]], [["a", "L’indicateur doit garder sa base, et un classement descriptif ne démontre pas une cause.", true, "Les deux limites sont nécessaires."], ["b", "La plus grande masse brute totale prouve toujours la meilleure performance globale.", false, "Surface, eau, qualité et ressources changent l’interprétation."]], "Choisir la question avant de désigner un meilleur lot.", ["moisture", "question", "causal"]), terms: ["outcome", "indicator", "yield", "perimeter"], next: "Quelle part du récolté répond réellement au débouché ?", keys: ["hemp", "moisture", "question", "causal"] }),
  lesson("outcomes", 2, { title: "Récolté et commercialisable", question: "Toute la matière récoltée devient-elle le produit attendu ?", objective: "Distinguer matière sèche entrante, pertes et fraction conforme au contrat.",
    essential: ["La masse récoltée ne se confond pas avec la fraction commercialisable pour un débouché donné. Le dossier sépare l’eau, les pertes physiques de matière sèche et la fraction écartée selon le contrat. Ces catégories doivent être disjointes pour ne pas compter deux fois la même matière. Un écart contractuel n’est pas automatiquement une preuve de danger alimentaire.", "Dans l’exercice, la part commercialisable est rapportée à la matière sèche entrante. Elle diffère du rendement commercialisable par hectare. La fiche réelle du Buddy Carmagnola rappelle une histoire de graines, fibres et cordages ; elle ne fixe ni ces proportions ni une qualité actuelle. Les critères pertinents dépendent du produit et du débouché réellement choisis."],
    example: "B fictif : 1 260 kg MS entrants, 63 kg MS perdus et 189 kg MS écartés selon le contrat ; il reste 1 008 kg MS commercialisables, soit 80 % des entrants.",
    deeper: "Pour A, les 960 kg MS entrants se répartissent en 48 perdus, 96 écartés et 816 commercialisables. Pour C, 1 200 se répartissent en 60, 60 et 1 080. Toutes ces valeurs sont inventées ; elles ne constituent pas des objectifs de tri ou de conservation. Une fraction non retenue pour ce contrat n’est pas automatiquement valorisable ailleurs : un autre usage demanderait sa propre vérification. Le lien Carmagnola permet de revenir à une histoire d’usages sans la prendre pour un bulletin du lot.", nodes: [["Entrant sec", "Base du bilan de matière"], ["Sorties distinctes", "Pertes, fraction écartée, commercialisable"], ["Contrat", "Critères du débouché, pas diagnostic sanitaire automatique"]],
    activity: activity("outcomes", 2, "diagram", "Lire le bilan de B", "Données entièrement fictives sur matière sèche : entrant 1 260 kg ; pertes physiques 63 ; fraction contractuellement écartée 189 ; commercialisable 1 008.", "Quelle lecture respecte le bilan ?", [["a", "1 008 kg MS sont commercialisables dans le contrat, soit 80 % de l’entrant sec.", true, "Les trois sorties disjointes totalisent bien 1 260 kg MS."], ["b", "La fraction écartée est nécessairement un aliment dangereux.", false, "Un motif contractuel ne suffit pas à établir un danger."], ["c", "La fiche Carmagnola garantit ces proportions pour tout lot.", false, "L’histoire du Buddy ne mesure pas le bilan actuel."]], [["a", "Le résultat doit garder son dénominateur et la définition de chaque fraction.", true, "Cela évite double compte et extrapolation."], ["b", "Le rendement par hectare et une part en pourcentage sont la même grandeur.", false, "Ils n’ont ni la même unité ni le même dénominateur."]], "Suivre la matière et les critères, sans confondre rejet et danger.", ["hemp", "moisture", "buddy"]), terms: ["marketable", "physical-loss", "contract-rejection", "mass-balance"], next: "Comment une erreur de base peut-elle renverser cette comparaison ?", keys: ["hemp", "moisture", "buddy"], buddyCodes: ["HH2026-045"] }),
];

const unitsLessons = [
  lesson("units", 1, { title: "L’eau fait partie du brut", question: "1 800 kg humides représentent-ils 1 800 kg de matière sèche ?", objective: "Repérer une confusion entre masse humide et matière sèche.",
    essential: ["Une masse brute humide contient de l’eau et de la matière sèche. Dans la convention utilisée ici, le pourcentage d’humidité rapporte la masse d’eau à la masse humide. Pour obtenir la matière sèche, on retire la fraction d’eau de cette masse ; on ne soustrait pas un pourcentage comme s’il s’agissait de kilogrammes. La base doit toujours être écrite.", "Le lot B fictif pèse 1 800 kg bruts à 30 % d’humidité sur base humide : sa matière sèche est 1 260 kg. Cela ne dit pas encore quelle fraction sera commercialisable. Une masse normalisée à une humidité commerciale est encore une autre expression, distincte d’une masse entièrement sèche. Aucun pourcentage d’exercice ne constitue une cible de stockage."],
    example: "Erreur fictive à repérer : la ligne 1 800 kg brut est copiée dans la colonne kg MS. La correction documentaire conserve 1 260 kg MS ; elle ne prescrit aucune opération de séchage.",
    deeper: "L’eau du lot B vaut ici 540 kg, et 540 + 1 260 reconstitue le brut de 1 800 kg. La publication UF/IFAS explique pourquoi normaliser à une humidité donnée demande de conserver le bilan de matière sèche, et non d’ajouter intuitivement un pourcentage. Le cours se limite au changement de base. Il ne transpose pas les humidités commerciales d’autres cultures au chanvre et ne transforme pas les valeurs fictives en recommandations de conservation.", nodes: [["Brut humide", "Eau + matière sèche"], ["Convention", "Eau / masse humide"], ["MS", "Masse après retrait comptable de l’eau"]],
    activity: activity("units", 1, "choice", "Trouver l’erreur d’unité", "Donnée fictive B : 1 800 kg bruts humides, 30 % d’eau sur base humide. Une note annonce 1 800 kg MS.", "Quelle correction est juste ?", [["a", "Il faut conserver 1 800 kg MS car la balance ne distingue pas l’eau.", false, "La balance mesure le brut ; la base humide permet de calculer une autre grandeur."], ["b", "La matière sèche vaut 1 260 kg ; le brut et la MS ne sont pas interchangeables.", true, "La fraction sèche vaut 70 % de 1 800 dans cet exemple."], ["c", "Il faut retrancher 30 kg puisque l’humidité vaut 30 %.", false, "Un pourcentage n’est pas une masse en kilogrammes."]], [["a", "Le pourcentage se rapporte à une base définie et doit être appliqué comme fraction.", true, "L’unité et le dénominateur évitent la confusion."], ["b", "Toute valeur d’humidité dans un exercice est une cible agronomique.", false, "Ces chiffres sont seulement des données pédagogiques inventées."]], "Ne pas comparer l’eau d’un lot à la matière sèche d’un autre.", ["moisture"]), terms: ["wet-mass", "dry-matter", "wet-basis", "normalization"], next: "Que change le choix du dénominateur : hectare, kilogramme ou heure ?", keys: ["moisture"] }),
  lesson("units", 2, { title: "Le dénominateur change la question", question: "Un total et une intensité racontent-ils la même chose ?", objective: "Distinguer quantité totale, rendement, part et ressource par unité de produit.",
    essential: ["Le rendement rapporte une quantité définie à une surface. Une part commercialisable rapporte une sortie à un entrant compatible. Une intensité de ressource peut rapporter une consommation à un kilogramme de produit commercialisable. Ces rapports ne répondent pas à la même question. Le numérateur et le dénominateur doivent porter sur des objets et périodes cohérents.", "Un lot peut consommer moins au total mais davantage par kilogramme retenu. À l’inverse, une meilleure intensité n’impose pas une baisse du total si la quantité produite augmente. Les ressources du dossier concernent seulement réception, tri, conditionnement et documentation ; culture et transport aval sont exclus. Une consommation électrique n’est ni une émission de gaz à effet de serre ni une analyse de cycle de vie complète."],
    example: "Dans un tableau fictif, les colonnes kg, kg/ha, pourcentage et kWh/kg MS commercialisable restent séparées. Aucun axe commun ne les additionne.",
    deeper: "La part commercialisable de A vaut 816/960, soit 85 %, alors que son rendement commercialisable sec vaut 816/0,8, soit 1 020 kg MS/ha. Les mêmes kilogrammes figurent au numérateur, mais les questions changent. Une comparaison de ressources doit aussi garder son périmètre : exclure la culture pour les trois lots permet une lecture partielle cohérente, pas un classement global de leurs impacts. Une donnée manquante sur une étape exclue ne peut pas être remplacée par zéro.", nodes: [["Total", "Quantité dans le périmètre"], ["Rapport", "Quantité par unité définie"], ["Comparaison", "Bases et frontières communes"]],
    activity: activity("units", 2, "matching", "Nommer le bon rapport", "Données fictives A : 816 kg MS commercialisables, 960 kg MS entrants, 0,8 ha.", "Quelle paire de résultats est correcte ?", [["a", "816/960 donne un rendement de 85 kg/ha.", false, "Ce rapport compare deux masses et produit une part, pas un rendement surfacique."], ["b", "816/0,8 donne une part commercialisable de 1 020 %.", false, "Le dénominateur est une surface : le résultat est en kg MS/ha."], ["c", "85 % des entrants secs sont commercialisables ; le rendement correspondant vaut 1 020 kg MS/ha.", true, "Les deux dénominateurs sont correctement nommés."]], [["a", "L’unité du dénominateur détermine le sens du rapport.", true, "Un nombre seul ne définit pas l’indicateur."], ["b", "Une baisse des kWh/kg prouve à elle seule une baisse de toute l’empreinte environnementale.", false, "Total, autres ressources et autres étapes restent à examiner."]], "Lire les deux côtés du rapport.", ["moisture", "question", "budget"]), terms: ["denominator", "intensity", "total", "perimeter"], next: "Même bien mesuré, un indicateur suffit-il à expliquer les limites d’une récolte ?", keys: ["moisture", "question", "budget"] }),
];

const limitsLessons = [
  lesson("limits", 1, { title: "Chercher ce qui limite réellement", question: "Plus d’un intrant apporte-t-il nécessairement un meilleur résultat ?", objective: "Distinguer mécanisme plausible, contrainte observée et bénéfice démontré.",
    essential: ["Une récolte résulte de plusieurs processus : développement, accès aux ressources, santé, aléas, récolte et conservation. Une difficulté apparente peut avoir plusieurs causes et une action ne résout pas forcément la contrainte dominante. Augmenter un apport ne démontre donc pas une amélioration. Il faut relier une hypothèse à des observations et à un résultat pertinent pour le débouché.", "Un mécanisme biologique possible n’est pas une garantie commerciale. Des essais d’inoculation mycorhizienne dans des champs de maïs ont observé des réponses différentes selon les sites. Ils ne fournissent pas une recette pour le chanvre. Présence d’un organisme, fonction possible et bénéfice mesuré restent trois niveaux distincts ; une promesse doit préciser lequel est réellement documenté."],
    example: "Un conseil fictif promet davantage de graines depuis la seule présence de racines colonisées. Le dossier ne mesure pourtant ni la quantité commercialisable ni un comparateur pertinent.",
    deeper: "L’étude de Lutz et collègues porte sur 54 champs de maïs suisses et un critère de croissance dans son protocole. Ce critère ne devient pas une mesure de graines de chanvre acceptées au contrat. Les résultats variables empêchent de sélectionner seulement les meilleurs sites pour annoncer une garantie universelle. Une hypothèse de nutrition, de santé ou de conservation doit être confrontée aux données adaptées, en conservant les autres explications plausibles et les limites de transfert entre systèmes.", nodes: [["Hypothèse", "Quel processus pourrait limiter ?"], ["Observation", "Quel indice soutient ou contredit ?"], ["Résultat", "Quel bénéfice est réellement mesuré ?"]],
    activity: activity("limits", 1, "dossier", "Un mécanisme ne suffit pas", "Une fiche fictive constate une colonisation racinaire puis annonce un gain universel de graines commercialisables.", "Quelle conclusion est justifiée ?", [["a", "La colonisation démontre tous les gains annoncés.", false, "Présence et résultat final ne sont pas identiques."], ["b", "Le gain reste à mesurer avec un comparateur et dans le contexte concerné.", true, "La promesse doit être testée à son propre niveau."], ["c", "Tout effet est impossible puisque les réponses peuvent varier.", false, "Une variabilité n’exclut pas des bénéfices dans certains contextes."]], [["a", "Un mécanisme possible ne remplace pas la mesure du critère revendiqué.", true, "On peut reconnaître un mécanisme sans inventer un rendement."], ["b", "Le meilleur résultat d’un autre végétal constitue une prévision garantie.", false, "Le transfert doit être justifié."]], "Chercher la contrainte et mesurer le bénéfice annoncé.", ["context", "question"]), terms: ["limiting-factor", "mechanism", "context", "hypothesis"], next: "Quelle observation supplémentaire réduirait le plus l’incertitude ?", keys: ["hemp", "context", "question"] }),
  lesson("limits", 2, { title: "Choisir la prochaine mesure utile", question: "Faut-il mesurer davantage ou mesurer autrement ?", objective: "Choisir une information qui distingue des explications plausibles.",
    essential: ["Une mesure utile répond à une question précise. Si les masses sont comparées sur des bases inconnues, vérifier la base et la méthode peut être plus informatif qu’ajouter une nouvelle pesée. Si la fraction écartée augmente, connaître les motifs de classement et leur chronologie peut orienter l’enquête. On cherche une information capable de départager des hypothèses, pas simplement un chiffre supplémentaire.", "Deux observations peuvent être recevables si elles réduisent des incertitudes différentes et explicites. Leur coût, leur délai et leur faisabilité comptent aussi. Une information manquante ne vaut pas zéro ; un symptôme ne constitue pas un diagnostic complet. La prochaine action doit préserver les preuves et pouvoir être révisée lorsque les résultats arrivent."],
    example: "Dossier fictif : davantage de graines sont écartées, mais les motifs ne sont pas détaillés et les bases des anciennes pesées sont incertaines. Deux vérifications documentaires complémentaires sont recevables.",
    deeper: "La démarche SARE commence par la question, puis choisit ce qu’il faut mesurer pour y répondre. Elle n’encourage pas à accumuler tous les indicateurs sans priorité. Dans l’exercice, vérifier les unités peut révéler un écart apparent ; détailler les motifs d’écart peut révéler une difficulté réelle de qualité. Ni l’une ni l’autre ne démontre seule une cause agronomique. Les résultats devront être rapprochés de l’historique, des lots et de la méthode, sans intervention universelle choisie à l’avance.", nodes: [["Incertitude", "Quelle information manque ?"], ["Mesure ciblée", "Quelle hypothèse aide-t-elle à départager ?"], ["Suite", "Comment le résultat changera-t-il la décision ?"]],
    activity: activity("limits", 2, "choice", "Choisir une observation supplémentaire", "Dossier fictif : hausse de la fraction écartée ; motifs absents ; bases des anciennes pesées non précisées.", "Quelle première vérification est recevable ?", [["a", "Vérifier les bases et méthodes des pesées pour tester l’hypothèse d’un écart de mesure.", true, "Cela peut distinguer un changement documentaire d’une différence matérielle."], ["b", "Obtenir les motifs détaillés d’écart et leurs dates pour situer la baisse de qualité.", true, "Cela précise ce qui a changé et à quel stade."], ["c", "Ajouter immédiatement un apport sans documenter les deux incertitudes.", false, "L’action ne répond pas aux informations manquantes du dossier."]], [["a", "La vérification choisie réduit une incertitude explicite et peut changer la suite de l’enquête.", true, "Cette justification est valable pour chacune des deux options recevables."], ["b", "Toute mesure nouvelle prouve automatiquement une causalité.", false, "Une mesure peut clarifier une observation sans isoler une cause."]], "Choisir une mesure pour ce qu’elle permettra de décider.", ["question", "methods", "causal"]), terms: ["information-gap", "useful-measure", "differential", "missing-data"], next: "Comment conserver les observations pour pouvoir les comparer ?", keys: ["question", "methods", "causal"] }),
];

const recordsLessons = [
  lesson("records", 1, { title: "Un journal qui permet de revenir aux faits", question: "Quelles lignes rendent une comparaison vérifiable ?", objective: "Relier lot, date, méthode et événement sans réécrire le passé.",
    essential: ["Un journal utile identifie la zone ou le lot, les dates, les quantités, les unités et les méthodes. Il distingue observation, intervention et interprétation. Les changements de matériel, de laboratoire, de classement ou de base de calcul doivent rester visibles. Sans ces repères, un écart peut être attribué à la plante alors qu’il provient de la manière de mesurer.", "Les anomalies, incidents et données absentes ont aussi leur place. Une correction conserve la valeur initiale, son motif et sa date plutôt que d’effacer silencieusement l’historique. Les pratiques enregistrées rendent une chaîne traçable ; elles ne prouvent pas à elles seules leur efficacité. Le journal prépare la comparaison et permet de revenir aux pièces qui soutiennent une conclusion."],
    example: "Une ligne fictive indique lot B, masse reçue, base humide, date et méthode. Une correction d’unité est ajoutée avec motif ; le relevé initial reste consultable.",
    deeper: "La charte de filière décrit des engagements d’enregistrement et de contrôle des lots. Elle ne démontre pas que chaque opérateur les respecte et ne remplace pas le résultat d’une analyse. Le guide SARE recommande des observations tout au long du projet, car un événement absent du carnet peut expliquer un résultat ultérieur. Un relevé précis rend cette explication examinable ; il ne transforme pas un récit en expérience contrôlée. Distinguer ce qui est observé de ce qui est supposé reste essentiel.", nodes: [["Identité", "Zone, lot et opérateur"], ["Mesure", "Date, unité, méthode et base"], ["Historique", "Événements, corrections et pièces"]],
    activity: activity("records", 1, "documents", "Corriger sans effacer", "Une unité a été mal recopiée dans un journal fictif. La pièce originale reste disponible.", "Quelle correction conserve une trace utile ?", [["a", "Remplacer silencieusement le nombre et supprimer l’original.", false, "Cela empêcherait de comprendre la correction."], ["b", "Garder l’erreur sans annotation pour ne pas modifier l’historique.", false, "Il faut corriger tout en conservant la trace du changement."], ["c", "Ajouter la valeur corrigée, sa base, son motif et la référence originale.", true, "Le résultat devient exploitable et la correction reste vérifiable."]], [["a", "La traçabilité relie le résultat à sa mesure et à ses modifications documentées.", true, "On peut revenir à la preuve initiale."], ["b", "Un carnet détaillé suffit à isoler toute cause.", false, "Il documente les faits mais ne remplace pas un comparateur."]], "Conserver un historique lisible, pas une histoire réécrite.", ["charter", "question", "methods"]), terms: ["record", "traceability", "measurement-method", "audit-trail"], next: "Que faire des données absentes ou atypiques ?", keys: ["charter", "question", "methods"] }),
  lesson("records", 2, { title: "Montrer aussi ce qui manque", question: "Une moyenne peut-elle cacher les lots difficiles ?", objective: "Distinguer absence de donnée, zéro et sélection des observations.",
    essential: ["Une valeur nulle est un résultat ; une valeur non relevée est une absence d’information. Dans les trois lots fictifs, l’eau de B n’a pas été relevée : elle ne doit pas être affichée comme zéro. Une moyenne calculée sur les seuls dossiers complets décrit ces dossiers, pas automatiquement toute la campagne. Le nombre d’observations et leurs exclusions doivent être visibles.", "Un résultat atypique peut provenir d’un incident, d’une erreur ou d’une variation réelle. On le vérifie avant de décider comment le traiter, selon une règle annoncée. Retirer après coup les lots défavorables parce qu’ils gênent la promesse biaise le bilan. Montrer la dispersion et les cas incomplets aide à conserver une conclusion proportionnée."],
    example: "Les relevés fictifs d’eau sont A = 0,4 m³, B = non relevé, C = 0,7 m³ dans le périmètre annoncé. B n’est pas déclaré le plus économe.",
    deeper: "Une comparaison doit expliquer combien de lots ont été suivis, lesquels manquent et pourquoi. Une panne de mesure n’a pas le même sens qu’une consommation réellement nulle. Les règles d’exclusion et de correction se définissent autant que possible avant l’analyse ; une exception justifiée reste documentée. La moyenne peut résumer, mais le détail montre parfois un résultat très variable ou une amélioration portée par un seul lot. Le journal et la représentation des données doivent permettre cette vérification.", nodes: [["Zéro", "Valeur observée dans une méthode"], ["Manquant", "Information non disponible"], ["Résumé", "Effectif, dispersion et exclusions"]],
    activity: activity("records", 2, "choice", "Le relevé absent de B", "Données fictives d’eau : A : 0,4 m³ ; B : non relevé ; C : 0,7 m³. Un classement met B en tête avec zéro.", "Quelle correction faut-il faire ?", [["a", "Afficher B comme inconnu et limiter le classement aux données effectivement disponibles.", true, "Le manque ne mesure pas une consommation nulle."], ["b", "Conserver zéro car le carnet ne contient aucun nombre.", false, "Absence d’écriture et valeur zéro diffèrent."], ["c", "Inventer la moyenne de A et C comme résultat mesuré de B.", false, "Une estimation ne doit pas être présentée comme une observation."]], [["a", "Le statut de la donnée fait partie de son interprétation.", true, "Mesuré, estimé et absent doivent rester distincts."], ["b", "Écarter un mauvais résultat suffit à prouver l’efficacité d’une action.", false, "La sélection des résultats peut fabriquer une amélioration apparente."]], "Ne pas rendre les inconnues artificiellement favorables.", ["question", "trials"]), terms: ["missing-data", "selection-bias", "variability", "outlier"], next: "Comment la qualité peut-elle évoluer entre récolte et classement final ?", keys: ["question", "trials", "budget"] }),
];

const handlingLessons = [
  lesson("handling", 1, { title: "La qualité continue après la récolte", question: "Une bonne quantité initiale garantit-elle le lot final ?", objective: "Identifier des étapes où quantité, intégrité et qualité peuvent évoluer.",
    essential: ["Entre récolte et produit livré, des pertes physiques, des séparations et des évolutions de qualité peuvent modifier le bilan. Des graines endommagées, des impuretés ou une altération liée aux conditions de conservation ne décrivent pas la même difficulté. Leur observation doit être reliée au stade où elle apparaît et au critère du débouché, sans proposer une correction universelle.", "Le guide chanvre distingue les attentes des filières graines et fibres et attire l’attention sur l’intégrité, l’échauffement et l’oxydation. Ces principes n’autorisent pas à deviner une cause depuis une seule photographie. Un tri ou une baisse d’humidité ne prouve pas qu’un lot suspect soit redevenu sûr. La sécurité et l’acceptation contractuelle nécessitent des preuves adaptées."],
    example: "Un dossier fictif montre une hausse des graines cassées entre réception et classement, sans mesure initiale comparable. L’enquête cherche des relevés aux mêmes étapes avant d’accuser une seule opération.",
    deeper: "La masse peut diminuer parce que de l’eau quitte le produit, parce que de la matière est physiquement perdue ou parce qu’une fraction est séparée : ces mécanismes n’ont pas la même signification. Les données doivent permettre de les distinguer. Les travaux sur la stabilité d’huile de graines montrent aussi que plusieurs marqueurs peuvent évoluer au cours du temps ; ils ne quantifient pas directement les pertes d’un lot de graines. Le cours ne donne aucun réglage, durée ou température de traitement.", nodes: [["Réception", "État initial documenté"], ["Parcours", "Événements et fractions séparées"], ["Classement final", "Critères et analyses correspondants"]],
    activity: activity("handling", 1, "dossier", "Situer une évolution", "Un lot fictif présente plus de fragments au classement final, mais le relevé de réception est incomplet.", "Quelle conclusion est proportionnée ?", [["a", "Une opération précise est déjà prouvée comme unique cause.", false, "Le dossier ne permet pas de localiser ainsi la cause."], ["b", "Il faut documenter l’état et les méthodes aux étapes pertinentes avant d’attribuer l’écart.", true, "La chronologie et la comparabilité sont nécessaires."], ["c", "Un tri rend automatiquement tout lot suspect apte à l’alimentation.", false, "Séparation et sécurité démontrée sont deux questions différentes."]], [["a", "Une évolution observée doit être reliée à des états comparables et à des événements documentés.", true, "Cela réduit les interprétations gratuites."], ["b", "Toute baisse de masse correspond à la même perte de matière sèche.", false, "L’eau, la matière perdue et la fraction séparée doivent être distinguées."]], "Suivre l’évolution sans inventer son mécanisme.", ["hemp", "oil", "methods"]), terms: ["integrity", "oxidation", "stage", "physical-loss"], next: "Les analyses successives décrivent-elles bien le même objet ?", keys: ["hemp", "oil", "methods"] }),
  lesson("handling", 2, { title: "Comparer des analyses compatibles", question: "Un changement de résultat signifie-t-il toujours un changement du lot ?", objective: "Vérifier échantillon, méthode, base et incertitude avant de conclure.",
    essential: ["Deux analyses sont comparables si leur objet et leur expression sont suffisamment compatibles : lot, partie prélevée, matrice, méthode, unité, base humide ou sèche et date. Un changement de laboratoire ou de méthode doit être examiné. Un échantillon précis ne représente pas automatiquement toute la matière, et une teneur ne mesure pas la quantité totale d’un composé dans le lot.", "Pour des fleurs uniquement considérées comme objets d’analyse, on conserve les mêmes limites : profil mesuré, incertitude, contaminants recherchés et critères absents. Le cours n’en tire aucun objectif de production, de puissance ou d’usage humain. Une valeur sous la limite de quantification n’est pas zéro ; une analyse absente n’est pas un résultat favorable."],
    example: "Deux bulletins fictifs expriment un même analyte sur bases humide et sèche. Avant d’annoncer une hausse, le joueur recherche les bases et les informations nécessaires à une comparaison compatible.",
    deeper: "Une variation de teneur peut résulter d’une différence d’eau, d’échantillonnage, de méthode ou d’une évolution réelle. La question ne se résout pas par le seul nombre affiché. Une analyse de matière végétale ne valide pas automatiquement un produit transformé ni sa stabilité future. Le périmètre du certificat doit donc accompagner tout graphique. Il est possible de conclure que la comparaison reste insuffisante ; ce n’est pas un échec, mais une description correcte du niveau de preuve disponible.", nodes: [["Même objet ?", "Lot, matrice et prélèvement"], ["Même expression ?", "Analyte, méthode, unité et base"], ["Conclusion", "Écart interprétable ou comparaison limitée"]],
    activity: activity("handling", 2, "documents", "Deux bulletins, deux bases", "Bulletins fictifs d’une matière végétale : l’un sur base humide, l’autre sur base sèche ; informations de prélèvement incomplètes.", "Quelle conclusion retenir ?", [["a", "Le plus grand nombre prouve à lui seul une amélioration de qualité.", false, "Les bases et échantillons peuvent différer."], ["b", "Un résultat sous LQ prouve une absence absolue de la molécule.", false, "La limite de méthode ne vaut pas zéro absolu."], ["c", "La comparaison demande des informations compatibles avant d’interpréter l’écart.", true, "On garde les limites de chaque bulletin."]], [["a", "Un nombre analytique reste attaché à sa matrice, sa méthode et sa base.", true, "Ces éléments conditionnent la comparaison."], ["b", "Toute teneur mesure directement la masse totale du composé dans le lot.", false, "Il faut aussi une masse de produit et une représentativité appropriées."]], "Vérifier la comparabilité avant de nommer une amélioration.", ["methods", "moisture"]), terms: ["sample", "matrix", "quantification-limit", "uncertainty"], next: "Quel dispositif permettrait de comparer une action de façon plus fiable ?", keys: ["methods", "moisture"] }),
];

const trialsLessons = [
  lesson("trials", 1, { title: "Quand plusieurs choses changent", question: "Peut-on attribuer un résultat à une seule nouveauté ?", objective: "Identifier une comparaison confondue et limiter sa conclusion.",
    essential: ["Un essai cherche à comparer des conditions définies. Si plusieurs choses changent ensemble, leurs effets peuvent devenir indissociables : origine du lot, parcelle, manutention, méthode de mesure ou critères de classement. Observer un meilleur résultat après un ensemble de changements ne permet pas d’attribuer le gain à une seule nouveauté. Le résultat descriptif reste utile, mais la conclusion causale doit être limitée.", "Le comparateur doit répondre à la question choisie. Comparer deux systèmes complets peut être pertinent si l’on accepte de conclure sur ces systèmes, pas sur chaque composant isolé. Pour examiner un facteur particulier, il faut un dispositif qui permette de le distinguer des autres influences. Multiplier les mesures dans une comparaison confondue ne supprime pas automatiquement ce problème."],
    example: "Un dossier fictif change simultanément fournisseur, parcelle, manutention et règle de classement. Une publicité attribue tout le résultat au fournisseur : le plan ne permet pas cette attribution.",
    deeper: "Le guide de l’Université du Minnesota explique que des différences de lots de semences ou d’autres interventions peuvent confondre l’effet recherché. La difficulté n’est pas seulement le nombre d’observations, mais ce qu’elles permettent de comparer. Un dispositif plus grand mais toujours confondu peut produire une estimation très précise d’un contraste ambigu. Avant de calculer davantage, il faut donc revenir à la question : effet d’une action précise ou comparaison de deux ensembles de pratiques ?",
    nodes: [["Contraste", "Qu’est-ce qui change ensemble ?"], ["Attribution", "Quel effet peut être séparé ?"], ["Conclusion", "Facteur isolé ou système complet ?"]],
    activity: activity("trials", 1, "dossier", "L’essai à plusieurs changements", "Comparaison fictive : fournisseur, parcelle, manutention et classement changent ensemble. Le résultat commercialisable augmente.", "Quelle conclusion est défendable ?", [["a", "Le fournisseur est démontré comme unique cause du gain.", false, "Les autres changements empêchent cette attribution isolée."], ["b", "Le contraste observé concerne l’ensemble des conditions ; le rôle de chaque changement reste indéterminé.", true, "La description est conservée sans excès causal."], ["c", "Un grand nombre de pesées rend automatiquement le contraste non confondu.", false, "Les pesées supplémentaires ne séparent pas les facteurs qui changent ensemble."]], [["a", "Le dispositif ne distingue pas les contributions des changements simultanés.", true, "C’est une limite de conception, pas une simple erreur de calcul."], ["b", "Toute comparaison de systèmes est inutile.", false, "Elle peut répondre à une question sur le système complet, si ce périmètre est assumé."]], "Conclure au niveau que le dispositif permet.", ["trials", "causal", "question"]), terms: ["confounding", "factor", "comparator", "causality"], next: "Comment préparer un contraste qui réponde mieux à la question ?", keys: ["trials", "causal", "question"] }),
  lesson("trials", 2, { title: "Préparer une comparaison fiable", question: "Que faut-il décider avant de regarder le résultat ?", objective: "Assembler question, comparateur, unités indépendantes et mesures prévues.",
    essential: ["Une comparaison fiable commence par une question et un critère principal définis à l’avance. On précise le comparateur, les unités auxquelles les conditions sont attribuées, les mesures et les règles de traitement des données. Répartir les conditions de façon aléatoire aide à limiter les biais systématiques. Des blocs peuvent prendre en compte une hétérogénéité connue, avec une comparaison organisée à leur intérieur.", "La répétition porte sur des unités suffisamment indépendantes pour la question posée. Plusieurs prélèvements dans une seule unité sont des sous-échantillons, pas automatiquement plusieurs répétitions de l’intervention. Le nombre nécessaire dépend de la variabilité et de la précision recherchée. Le plan doit rester réalisable, autorisé et cohérent avec l’analyse prévue, sans chiffre magique universel."],
    example: "Un projet fictif compare deux organisations documentaires de suivi de lots : critère de complétude défini, plusieurs unités indépendantes, attribution prévue et même méthode de vérification.",
    deeper: "Les blocs ne servent pas à choisir après coup les résultats qui arrangent : ils organisent une source de variation identifiée dans le plan. La randomisation ne garantit pas une égalité parfaite de chaque caractéristique dans un petit essai ; elle réduit une attribution systématiquement favorable. Une mesure répétée peut améliorer la connaissance d’une unité sans augmenter le nombre d’unités expérimentales. Préparer le plan et l’analyse ensemble évite de demander aux données une conclusion qu’elles ne peuvent pas soutenir.", nodes: [["Question et critère", "Définis avant les résultats"], ["Dispositif", "Comparateur, attribution et répétitions"], ["Mesures", "Méthodes, données absentes et analyse prévues"]],
    activity: activity("trials", 2, "order", "Choisir le plan le plus informatif", "Projet fictif et autorisé : comparer deux organisations de suivi documentaire, sans modifier les programmes de culture.", "Quel plan répond le mieux à la question ?", [["a", "Définir critère et comparateur, attribuer les conditions sans sélection favorable, répéter sur des unités distinctes et garder les mêmes mesures.", true, "Ces éléments rendent le contraste plus interprétable."], ["b", "Choisir les meilleurs lots pour la nouveauté puis appeler chaque pesée une répétition indépendante.", false, "La sélection et la pseudoréplication faussent la lecture."], ["c", "Choisir le critère seulement après avoir vu lequel donne le plus grand gain.", false, "Cette sélection favorise un résultat spectaculaire au lieu de tester la question prévue."]], [["a", "Le plan doit réduire les biais et produire des données adaptées au contraste annoncé.", true, "La justification relie conception et conclusion."], ["b", "Un nombre fixe de répétitions suffit dans toutes les situations.", false, "La variabilité et la précision attendue doivent être prises en compte."]], "Concevoir le contraste avant de récolter les résultats.", ["trials", "blocks", "question"]), terms: ["experimental-unit", "replication", "subsample", "randomization", "block", "primary-outcome"], next: "Pourquoi un simple avant/après reste-t-il souvent ambigu ?", keys: ["trials", "blocks", "question"] }),
];

const beforeAfterLessons = [
  lesson("before-after", 1, { title: "Après ne signifie pas à cause de", question: "Une meilleure année prouve-t-elle l’effet d’une nouveauté ?", objective: "Repérer les autres changements et le comparateur manquant.",
    essential: ["Un avant/après décrit une succession dans le temps. Il ne montre pas directement ce qui se serait produit au même moment sans la nouveauté. Saison, zone, état initial, méthode ou exigences commerciales peuvent aussi changer. La temporalité est nécessaire pour expliquer un effet, mais elle ne suffit pas à isoler la cause d’une différence observée.", "Un suivi peut néanmoins être utile : il révèle une évolution et aide à formuler des hypothèses. On recherche ensuite un comparateur pertinent, des mesures compatibles et les événements du journal. Une amélioration après une période exceptionnellement mauvaise peut aussi refléter une variation naturelle. Il faut conserver cette possibilité plutôt que transformer chaque rebond en preuve d’efficacité."],
    example: "Un dossier fictif compare deux années, mais la parcelle et les critères commerciaux ont changé. La hausse du produit accepté ne peut pas être attribuée automatiquement à la seule nouveauté annoncée.",
    deeper: "Les trois lots A/B/C du début proviennent de zones distinctes d’une même campagne : ils ne sont pas des étapes successives. À l’inverse, deux campagnes successives ne deviennent pas un essai contrôlé par le seul fait d’avoir deux nombres. Une analyse plus élaborée peut parfois exploiter des séries et des comparateurs, sous hypothèses explicites ; ici ces données manquent. La conclusion appropriée distingue donc ce qui a changé dans les observations de ce que l’on peut attribuer à une cause précise.", nodes: [["Avant / après", "Évolution observée"], ["Autres changements", "Contexte, méthode et critères"], ["Contrefactuel", "Ce qui manque pour attribuer l’effet"]],
    activity: activity("before-after", 1, "chronology", "Lire deux campagnes", "Dossier fictif : davantage de produit accepté en 2026 qu’en 2025, avec autre zone et autre règle de classement.", "Quelle conclusion garder ?", [["a", "L’évolution est observée ; l’effet isolé d’une nouveauté n’est pas établi.", true, "La comparaison change plusieurs dimensions."], ["b", "Le seul ordre chronologique démontre la cause.", false, "D’autres changements peuvent expliquer tout ou partie de l’écart."], ["c", "Toute donnée de suivi doit être supprimée si elle n’est pas expérimentale.", false, "Elle reste utile pour décrire et préparer une enquête."]], [["a", "L’avant/après ne fournit pas à lui seul le résultat qui aurait eu lieu sans la nouveauté.", true, "C’est la comparaison causale manquante."], ["b", "Un rebond après une mauvaise année ne peut jamais être naturel.", false, "La variabilité du contexte doit rester une explication possible."]], "Conserver l’évolution sans lui attribuer une cause automatique.", ["causal", "trials", "question"]), terms: ["before-after", "counterfactual", "temporal-trend", "confounding"], next: "Que montrent plusieurs résultats plutôt qu’un seul chiffre moyen ?", keys: ["causal", "trials", "question"] }),
  lesson("before-after", 2, { title: "Un effet, sa dispersion et ses limites", question: "Une moyenne positive signifie-t-elle un gain partout ?", objective: "Distinguer effet estimé, incertitude et portée de généralisation.",
    essential: ["Une moyenne résume des observations, mais elle peut masquer des réponses différentes selon les unités ou les sites. L’effectif, la dispersion et l’incertitude aident à apprécier la solidité du résultat. Une différence observée n’est pas automatiquement une différence fiable, et une différence difficile à distinguer du bruit n’établit pas forcément l’absence de tout effet.", "La pertinence pratique se juge aussi sur le critère choisi, l’ampleur plausible et les coûts ou contraintes associés. Une amélioration statistique ne suffit pas à décider seule. Répéter une comparaison dans d’autres contextes renseigne son transfert, sans garantir une réponse identique partout. Les résultats défavorables ou incertains doivent rester visibles, au même titre que les succès."],
    example: "Une série fictive contient un grand gain et plusieurs petits écarts de sens opposés. Le joueur demande les valeurs par unité et l’incertitude, plutôt que de retenir seulement la meilleure observation.",
    deeper: "L’étude mycorhizienne sur maïs illustre une réponse variable entre champs ; elle ne donne pas un bénéfice constant ni un rendement de graines de chanvre. Les données doivent rester attachées au modèle et au critère mesuré. Dans un petit essai, l’absence de différence convaincante peut refléter un effet faible, une grande variabilité ou une précision insuffisante. Le résultat ne justifie ni la promesse fonctionne toujours ni son inverse ne peut jamais fonctionner. Il guide la prochaine question et le besoin de confirmation.", nodes: [["Estimation", "Sens et ampleur du contraste"], ["Incertitude", "Variabilité et précision"], ["Portée", "Critère, contexte et utilité pratique"]],
    activity: activity("before-after", 2, "choice", "Ne pas choisir seulement le meilleur", "Une série fictive montre des résultats variables entre unités ; la publicité ne retient que le gain maximal.", "Quelle demande améliore l’interprétation ?", [["a", "Remplacer tous les écarts par le maximum observé.", false, "Cela masque la variabilité et favorise une promesse abusive."], ["b", "Examiner toutes les unités, l’effet estimé, son incertitude et le critère mesuré.", true, "On peut alors apprécier la solidité et la portée du résultat."], ["c", "Déclarer chaque différence positive certaine sans tenir compte de la dispersion.", false, "Une observation positive ne suffit pas à établir la fiabilité du contraste."]], [["a", "La moyenne et le maximum ne décrivent pas seuls la diversité des réponses.", true, "Il faut conserver les résultats incertains ou défavorables."], ["b", "Un résultat non concluant prouve toujours un effet exactement nul.", false, "La précision peut être insuffisante pour trancher."]], "Montrer le résultat et sa marge d’incertitude.", ["trials", "context", "budget"]), terms: ["mean", "variability", "uncertainty", "transferability", "practical-relevance"], next: "Un gain de produit vaut-il les ressources et contraintes supplémentaires ?", keys: ["trials", "context", "budget"] }),
];

const tradeoffsLessons = [
  lesson("tradeoffs", 1, { title: "Compter ce qui change", question: "Plus de produit commercialisable signifie-t-il plus de marge ?", objective: "Distinguer résultat physique, dépenses partielles et bilan économique.",
    essential: ["Un gain physique ne devient pas automatiquement un gain économique. Il faut examiner les recettes pertinentes, les dépenses qui changent, le travail, les pertes et les risques. Un budget partiel compare les conséquences d’un changement dans un périmètre annoncé. Il ne représente pas nécessairement le coût complet de l’activité, et ses valeurs incertaines doivent rester identifiées comme telles.", "Les dépenses du dossier fictif concernent seulement réception, tri, conditionnement et documentation. Culture, transport aval, amortissements et salaire propre sont exclus. Aucun prix de vente n’est fourni : on ne calcule donc ni marge ni rentabilité complète. Une dépense plus faible peut être un avantage sur ce critère, sans suffire à désigner la meilleure option pour tous les objectifs."],
    example: "Dépenses partielles fictives : A : 400 €, B : 720 €, C : 620 €. Leurs quantités commercialisables diffèrent. Ces données ne donnent pas les recettes ni une marge complète.",
    deeper: "Le cadre de budget partiel distingue les revenus supplémentaires et coûts évités des dépenses supplémentaires et revenus perdus. Son intérêt dépend de la qualité des hypothèses. On peut examiner plusieurs scénarios lorsque certaines données sont incertaines, mais on ne doit pas les présenter comme des résultats mesurés. Les facteurs non monétaires, notamment la disponibilité du travail ou la fiabilité documentaire, peuvent aussi compter. Ici, les chiffres sont un exercice de lecture des frontières, sans recommandation d’investissement ni prévision de prix.", nodes: [["Résultat physique", "Produit retenu et qualité"], ["Conséquences", "Recettes, dépenses et travail qui changent"], ["Limites", "Postes absents et hypothèses"]],
    activity: activity("tradeoffs", 1, "dossier", "Une marge impossible à calculer", "Tableau fictif : dépenses partielles A : 400 €, B : 720 €, C : 620 € ; aucun prix de vente ; plusieurs postes exclus.", "Que peut-on conclure ?", [["a", "A possède nécessairement la meilleure marge complète.", false, "Les recettes et coûts complets ne sont pas connus."], ["b", "C est nécessairement le moins rentable puisque son total dépasse A.", false, "Le produit commercialisable et les recettes diffèrent potentiellement."], ["c", "A engage moins de dépenses dans ce périmètre ; la marge complète reste inconnue.", true, "On conserve l’information réellement disponible."]], [["a", "Une dépense partielle n’est ni un coût complet ni une recette moins tous les coûts.", true, "Le périmètre limite la conclusion économique."], ["b", "Un chiffre en euros couvre automatiquement tous les postes.", false, "L’unité ne décrit pas les frontières du calcul."]], "Ne pas appeler rentabilité un tableau incomplet de dépenses.", ["budget", "question"]), terms: ["partial-budget", "partial-cost", "revenue", "margin", "opportunity-cost"], next: "Comment choisir lorsque les objectifs se contredisent ?", keys: ["budget", "question"] }),
  lesson("tradeoffs", 2, { title: "Défendre un compromis explicite", question: "Faut-il absolument désigner un vainqueur unique ?", objective: "Comparer plusieurs critères et justifier une préférence conditionnelle.",
    essential: ["Une option peut mieux répondre à un objectif et moins bien à un autre. On commence par distinguer les contraintes à respecter des préférences entre résultats recevables. Un choix peut privilégier la quantité commercialisable, le travail disponible, les dépenses ou la régularité, à condition de nommer ce compromis et de conserver les informations manquantes.", "Dans le dossier, C fournit davantage de matière sèche commercialisable par hectare que A, mais A mobilise moins de travail, d’énergie et de dépenses partielles au total. Cela ne crée pas un classement universel. Les surfaces, les bases et le périmètre doivent rester visibles. L’eau de B est inconnue ; elle ne peut pas servir d’avantage imaginaire dans la décision."],
    example: "Comparaison fictive A/C : A limite davantage les dépenses et heures du périmètre ; C obtient plus de produit commercialisable sec par hectare. Sans priorité supplémentaire, deux lectures conditionnelles sont recevables.",
    deeper: "Une option n’est dominée au sens d’une comparaison multicritère que si une autre fait au moins aussi bien sur tous les critères retenus et mieux sur au moins un, avec des données compatibles. Ce jugement dépend donc des critères choisis et des données disponibles. Une préférence n’est pas une découverte scientifique : elle doit être explicite. De nouvelles contraintes de qualité, de travail ou de sécurité peuvent modifier le choix, même si le classement d’un indicateur physique reste inchangé.", nodes: [["Contraintes", "Ce qui doit être respecté"], ["Critères", "Ce qui peut être privilégié"], ["Choix", "Compromis explicite et révisable"]],
    activity: activity("tradeoffs", 2, "choice", "Deux préférences défendables", "Dossier fictif A/C, sans priorité imposée : A demande moins de dépenses et d’heures au total ; C fournit plus de matière sèche commercialisable par hectare.", "Quelle lecture conditionnelle est recevable ?", [["a", "Privilégier A si la priorité est de limiter ces dépenses et heures, en reconnaissant son résultat surfacique inférieur.", true, "La préférence et son compromis sont explicités."], ["b", "Privilégier C si la priorité est le résultat commercialisable par hectare, en reconnaissant les charges partielles plus fortes.", true, "La préférence et son compromis sont explicités."], ["c", "Déclarer l’un supérieur sur tous les critères sans préciser les priorités.", false, "Le dossier présente justement des avantages différents."]], [["a", "Le choix annonce le critère privilégié et reconnaît le compromis plutôt que de prétendre à une supériorité universelle.", true, "Cette raison soutient chacune des deux lectures recevables."], ["b", "Une donnée absente peut être remplacée par la valeur qui favorise le choix.", false, "Les inconnues doivent rester visibles."]], "Un choix justifié peut rester conditionnel.", ["budget", "question"]), terms: ["tradeoff", "constraint", "priority", "dominance", "scenario"], next: "Comment reconnaître un conseil qui efface ces conditions ?", keys: ["budget", "question"] }),
];

const tipsLessons = [
  lesson("tips", 1, { title: "Mettre une promesse à l’épreuve", question: "Que manque-t-il derrière fonctionne toujours ?", objective: "Transformer une astuce en question vérifiable.",
    essential: ["Un conseil utile précise pour quel objectif, quel produit, quel contexte et avec quelles preuves il est proposé. Une histoire de variété, un mécanisme plausible ou une photo spectaculaire ne suffisent pas à garantir un résultat. Il faut demander le critère mesuré, le comparateur, les répétitions, les résultats défavorables et les limites de transfert. La date et les intérêts de l’émetteur comptent également.", "Une hypothèse peut être intéressante sans être déjà démontrée. On peut choisir de mieux observer, de chercher des données indépendantes ou de préparer une comparaison prudente avant d’adopter une action. L’amélioration doit être mesurée au niveau annoncé : davantage de biomasse ne prouve pas automatiquement davantage de graines commercialisables, ni une qualité meilleure ou un moindre coût complet."],
    example: "Une publicité fictive promet un gain universel depuis le meilleur résultat d’un autre végétal. Le joueur reformule : quel résultat, dans quel système, comparé à quoi et avec quelles limites ?",
    deeper: "L’étude sur les mycorhizes illustre la différence entre preuve de fonctionnement possible et réponse constante dans tous les sites. Une communication peut sélectionner le meilleur cas, changer d’indicateur ou omettre les coûts pour rendre sa promesse plus convaincante. Le journal et les documents originaux permettent de repérer ces glissements. La démarche critique ne consiste pas à rejeter toute nouveauté : elle consiste à calibrer l’action et la confiance au niveau de preuve, puis à vérifier si le résultat attendu se produit réellement.", nodes: [["Promesse", "Objectif et portée annoncés"], ["Preuves", "Critère, comparateur, résultats et intérêts"], ["Décision", "Observation, essai prudent ou révision"]],
    activity: activity("tips", 1, "documents", "Interroger l’astuce universelle", "Une annonce fictive cite un maximum obtenu sur une autre culture et promet la même hausse de graines commercialisables partout.", "Quelle réponse est justifiée ?", [["a", "Demander les résultats complets, le critère réel et les conditions avant d’étendre la promesse.", true, "La question remet la preuve à son niveau exact."], ["b", "Le maximum publié constitue une garantie pour toute situation.", false, "Il ne décrit ni la variabilité ni le transfert."], ["c", "Tout mécanisme plausible est nécessairement inutile s’il n’est pas universel.", false, "Un intérêt contextuel reste possible et doit être évalué."]], [["a", "La confiance doit suivre la portée des données, pas la force du slogan.", true, "On peut examiner une nouveauté sans promettre un résultat certain."], ["b", "Un changement d’indicateur rend toujours les résultats équivalents.", false, "Biomasse, graines, qualité et coût sont des critères distincts."]], "Transformer la promesse en comparaison vérifiable.", ["context", "question", "trials", "budget"]), terms: ["claim", "selective-reporting", "transferability", "primary-outcome"], next: "Comment réunir toutes ces distinctions face à une baisse de qualité ?", keys: ["context", "question", "trials", "budget"] }),
  lesson("tips", 2, { title: "Enquêter avant d’intervenir", question: "Que faire lorsque les indices permettent plusieurs explications ?", objective: "Relier informations, hypothèses et suivi dans une décision prudente.",
    essential: ["Le dossier final fictif concerne des graines de chanvre autorisé en Bretagne. En 2026, des grains cassés, une odeur différente et davantage de refus sont signalés par rapport à 2025. Mais les critères commerciaux se sont durcis, les prélèvements diffèrent et plusieurs étapes de manutention ont changé. Le journal de stockage est incomplet ; une condensation sur une paroi ne démontre pas une moisissure dans les graines.", "Plusieurs hypothèses restent donc recevables, à relier chacune à une pièce pertinente. On peut recueillir des observations comparables ou conserver l’identité du lot et le mettre en attente par précaution. La justification doit nommer l’incertitude ou le risque à examiner. Le suivi mesure ensuite des critères définis, sans inventer diagnostic, recette ou causalité."],
    example: "Dossier entièrement fictif : prélèvement composite en 2025, dessus du lot en 2026 ; autre saison et parcelle ; nom de variété identique mais identité du lot non garantie. Les trois lots A/B/C sont un exercice séparé.",
    deeper: "L’enquête mobilise anatomie et matière récoltée, diversité et identité, sol et racines, climat, santé végétale, composition analytique, produits et traçabilité. Ces renvois aident à formuler des questions, sans transférer un profil de fleur à une graine. Une odeur seule ne diagnostique ni moisissure ni carence. Une observation supplémentaire et une attente conservant la traçabilité peuvent être deux premières réponses recevables selon leur justification ; un suivi comparable ou une comparaison préparée peuvent ensuite tester les hypothèses. L’atelier n’autorise aucune remise en consommation d’un lot suspect.", nodes: [["Pièces", "Critères, prélèvements, manutention et journal"], ["Hypothèses", "Plusieurs explications reliées aux indices"], ["Action et suivi", "Prudence, mesures comparables et décision révisable"]],
    activity: activity("tips", 2, "dossier", "Défendre une prochaine étape", "Enquête fictive Bretagne : grains cassés, odeur différente et refus en hausse ; critères et prélèvements modifiés, manutention changée, journal incomplet. Aucun diagnostic confirmé.", "Quelle première réponse est recevable ?", [["a", "Recueillir des observations comparables et détailler les motifs de refus pour réduire l’incertitude.", true, "Cette voie cherche à départager les hypothèses avec des données pertinentes."], ["b", "Conserver l’identité du lot et le mettre en attente par précaution, puis compléter les vérifications.", true, "Cette voie évite une validation prématurée tout en préservant la chaîne de preuve."], ["c", "Diagnostiquer une moisissure ou une carence depuis l’odeur seule et appliquer une correction universelle.", false, "Les indices ne suffisent pas à ce diagnostic ni à cette action."]], [["a", "La réponse garde les hypothèses ouvertes, préserve les preuves et prévoit des vérifications adaptées avant de conclure.", true, "Cette justification soutient chacune des deux réponses recevables."], ["b", "Le nom de la variété garantit la même qualité d’une année à l’autre.", false, "Nom, lot, contexte et qualité mesurée restent distincts."]], "Observer, comparer, expliciter les limites, agir proportionnellement et mesurer la suite.", ["hemp", "methods", "question", "causal", "charter"]), terms: ["differential", "precaution", "follow-up", "traceability", "useful-measure"], next: "Pouvez-vous expliquer quelle preuve vous ferait changer de conclusion ?", keys: ["hemp", "methods", "question", "causal", "charter"] }),
];

function checkpoint(ch: string, title: string, scenario: string, prompt: string, rows: readonly Row[], reasons: readonly Row[], takeaway: string, keys: readonly string[]) {
  return activity(ch, "checkpoint", "dossier", title, scenario, prompt, rows, reasons, takeaway, keys);
}
function chapter(id: string, number: number, title: string, introduction: string, lessons: readonly HistoryLesson[], cp: HistoryActivity, uses: string): HistoryChapter {
  return { id, number, title, introduction, lessons, checkpoint: cp, context: { who: "Producteurs de chanvre autorisé, opérateurs de lots, laboratoires et lecteurs des résultats.", where: "Exemples pédagogiques fictifs, principalement graines et fibres ; sources étrangères limitées à leurs principes et contextes.", uses, transformations: "Mesurer, suivre les fractions et comparer des décisions ; aucune recette de production ni réglage de transformation.", evidence: "Documents, méthodes et publications originales avec accès et limites ; les chiffres des exercices sont inventés.", labourAndTrade: "Distinguer produit récolté, critères contractuels, dépenses partielles, travail et ressources ; aucun prix de marché ni revenu réel inventé." } };
}
