function q(ch: string, n: number, part: number, prompt: string, texts: readonly [string, string, string, string], keys: readonly string[], difficulty: "easy" | "medium" = "medium"): HistoryQuizQuestion {
  return { id: "harvest-" + ch + "-q" + String(n).padStart(2, "0"), chapterId: ch, prompt, options: texts.map((text, index) => ({ id: ["a", "b", "c", "d"][index], text })), difficulty, lessonId: "prevention", sectionId: lid(ch, part), sources: refs(keys), ...(ch === "outcomes" && n === 4 ? { buddyCodes: ["HH2026-045"] } : {}) };
}
